import{_ as i,l as d,o as e,c as s,v as t,p as c,x as o,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"比较器","description":"","frontmatter":{"title":"比较器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/comparator-circuit.md","filePath":"cs/comparator-circuit.md","lastUpdated":1789023840000}'),h={name:"cs/comparator-circuit.md"};function A(u,a,m,E,_,b){const r=d("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="比较器" tabindex="-1">比较器 <a class="header-anchor" href="#比较器" aria-label="Permalink to &quot;比较器&quot;">​</a></h1><div class="epigraph"><p>相等是逐位同或再与；大小则要声明按无符号还是补码读，不能共用同一条「最高位」故事。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/alu-datapath">ALU 数据通路</a>把 <code>slt</code> 并进减法结果。本课不重画 ALU 内部 MUX，也不从排序算法另起。缺口是：比较作为<strong>独立组合功能</strong>要说清三种输出——相等、无符号小于、有符号小于——以及它们与<a href="/cs/twos-complement">补码</a>两种读法的关系。后课分支 <code>beq</code>/<code>blt</code>/<code>bltu</code> 依赖这些位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ALU 减法能做 <code>slt</code>，但相等更便宜：不必走 CLA。缺口因此不是新的整数定义，而是比较器电路：\\(\\mathrm{eq}=\\bigwedge_i (a_i\\leftrightarrow b_i)\\)；无符号大小从最高位向低扫描第一位差异，或用减法的进位/借位。有符号大小不能只看最高位：负数最高位为 1，但 \\(-1\\gt -2\\)。正确做法是按补码语义用减法溢出与符号，或先比较符号再比较幅度。</p><p>RISC-V 把三种比较拆进不同指令，同一比特、不同旗标。本课只钉组合如何出这三位。</p><h3 id="最高位不是无符号的「符号」" tabindex="-1">最高位不是无符号的「符号」 <a class="header-anchor" href="#最高位不是无符号的「符号」" aria-label="Permalink to &quot;最高位不是无符号的「符号」&quot;">​</a></h3><p>无符号比较把最高位当最大权，<a href="/cs/positional-notation">进制课</a>的 \\(2^{n-1}\\)。有符号才把该位当负权。把「看 MSB」当成万能比较，<code>bltu</code> 与 <code>blt</code> 会接反。</p><p><span class="marginnote">Harris 有专用比较器级联。Patterson/Hennessy 强调 <code>slt</code> 与 <code>sltu</code>。分支用减法零旗标或比较器，单周期里常复用 ALU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>相等：异或树再或非。无符号：从 MSB 起的优先编码「谁先出现 1」。有符号：若符号不同则负者小；符号同则化为无符号比较幅度（或减一次看旗标）。延迟：相等可浅；全大小比较与加法器同阶，CLA 减法仍可用。</p>',11)),(e(),c(p,null,{default:o(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22A%20%E4%B8%8E%20B%22%5D%20--%3E%20EQ%5B%22%E9%80%90%E4%BD%8D%E7%9B%B8%E7%AD%89%22%5D%0A%20%20AB%20--%3E%20US%5B%22%E6%97%A0%E7%AC%A6%E5%8F%B7%E5%A4%A7%E5%B0%8F%22%5D%0A%20%20AB%20--%3E%20S%5B%22%E8%A1%A5%E7%A0%81%E5%A4%A7%E5%B0%8F%22%5D%0A%20%20EQ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9C%80%E8%A6%81%E8%AE%B0%E5%BF%86%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 <code>beq</code> 看 eq 或 ALU 零。<code>blt</code> 看有符号小于，<code>bltu</code> 看无符号。立即数比较 <code>slti</code> 同一通路。比较器也可以不进 ALU、单独放在分支路径上，以缩短某些设计的关键路径——那是单周期课的布局选择。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较浮点（754 的 NaN 无序，规则不同）。不把字符串字典序提前。三态、模拟电压比较器不是数字块。</p><p>组合到此仍无记忆：比较完结果若不存下来，下一瞬输入变就丢。下一课锁存与触发器才开始时序。</p><p>后课默认：整数比较分 eq / 有符号 / 无符号三套；硬件可复用减法或独立比较器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>相等是按位同；大小必须先声明编码。</li><li><code>blt</code> 与 <code>bltu</code> 不是同一旗标。</li><li>比较仍是组合；状态要从下一课开始。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const q=i(h,[["render",A]]);export{f as __pageData,q as default};
